import java.util.Scanner;

public class Main {
    static class UnionFind {
        int[] parent;
        int[] rank;

        public void build(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; ++i) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public int findSet(int x) {
            if (parent[x] != x) {
                parent[x] = findSet(parent[x]);
            }
            return parent[x];
        }

        public void merge(int a, int b) {
            a = findSet(a);
            b = findSet(b);
            if (a != b) {
                if (rank[a] < rank[b]) {
                    int temp = a;
                    a = b;
                    b = temp;
                }
                parent[b] = a;
                if (rank[a] == rank[b]) {
                    rank[a]++;
                }
            }
        }
    }

    public static long powerMod(long base, int exp, int mod) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        final int MOD = 1000000007;

        if (k == 0) {
            System.out.println(powerMod(n, n - 1, MOD));
            sc.close();
            return;
        }

        UnionFind uf = new UnionFind();
        uf.build(n);
        for (int i = 0; i < n; ++i) {
            uf.merge(i, (int)((long)i * k % n));
        }

        long result = 1;
        for (int i = 0; i < n; ++i) {
            int root = uf.findSet(i);
            if (root != i) continue;
            long t = powerMod(k, uf.rank[root], n);
            if (t == 1) {
                result = (result * n) % MOD;
            }
        }
        System.out.println(result);
        sc.close();
    }
}
